//! Share and export: email as text, .docx, .txt, PDF, print; bibliography (Harvard/APA/
//! Vancouver, BibTeX, RIS). Exports keep the AI labels, text-origin marking and references.
//!
//! INTERFACE FILE: the public functions here are what the app calls.
//!
//! Every export starts with the article's label, title, byline, "Generated by …" line, the
//! link to the original paper (when there is one) and a legend of the three origin styles, and
//! ends with the numbered reference list and the validation notes. The per-format writers live
//! in `txt.rs`, `docx.rs` and `pdf.rs`; the shared front matter / reference helpers are here.

use std::path::{Path, PathBuf};

use anyhow::{Context, Result};

use crate::model::*;

pub mod cite;
mod docx;
mod metrics;
mod pdf;
mod txt;

#[cfg(test)]
pub(crate) mod tests;

/// Plain-text export. Origin marking in text form: AI-written passages wrapped as
/// "⟦AI: …⟧", reworded originals as "⟦Reworded: …⟧ (original: …)", unverified as "[unverified]",
/// a legend at the top, the article's label (e.g. "AI interpretation – not the original
/// paper") and the reference list at the end. Lines holding AI-written text also start with
/// a "▍ " margin bar.
pub fn to_txt(a: &Article, style: CitationStyle) -> String {
    txt::render(a, style)
}

/// Word document: AI-written text in purple with a left border (margin bar), reworded text
/// underlined with the original as a footnote, original text plain, links green, label banner,
/// legend, references at the end.
pub fn to_docx(a: &Article, style: CitationStyle, path: &Path) -> Result<()> {
    let bytes = docx::render(a, style)?;
    std::fs::write(path, bytes).with_context(|| format!("could not write {}", path.display()))
}

/// The .docx file as bytes (for callers that want to stream or attach it).
pub fn docx_bytes(a: &Article, style: CitationStyle) -> Result<Vec<u8>> {
    docx::render(a, style)
}

/// PDF with the same marking as the docx (purple + margin bar for AI text so it survives
/// greyscale printing, underline for reworded text, label, legend, references).
pub fn to_pdf(a: &Article, style: CitationStyle, path: &Path) -> Result<()> {
    let bytes = pdf::render(a, style)?;
    std::fs::write(path, bytes).with_context(|| format!("could not write {}", path.display()))
}

/// The PDF as bytes, plus its page count.
pub fn pdf_bytes(a: &Article, style: CitationStyle) -> Result<(Vec<u8>, usize)> {
    pdf::render_with_pages(a, style)
}

/// Print via the system: writes a temporary PDF and sends it to the default printer with
/// `lp`, falling back to opening the PDF in the default viewer to print from there.
/// Returns a message for the user saying what happened.
pub fn print(a: &Article, style: CitationStyle) -> Result<String> {
    // TODO(windows): no `lp`; open the PDF with the default viewer (or ShellExecute "print").
    let path = print_pdf_path(a, style)?;
    if let Some(lp) = find_in_path("lp") {
        match std::process::Command::new(lp).arg("-t").arg(&a.title).arg(&path).output() {
            Ok(out) if out.status.success() => {
                let msg = String::from_utf8_lossy(&out.stdout).trim().to_string();
                return Ok(if msg.is_empty() {
                    "Sent to the default printer.".to_string()
                } else {
                    format!("Sent to the default printer ({msg}).")
                });
            }
            Ok(out) => {
                log::warn!("lp failed: {}", String::from_utf8_lossy(&out.stderr).trim());
            }
            Err(e) => log::warn!("could not run lp: {e}"),
        }
    }
    open::that_detached(&path).with_context(|| format!("could not open {}", path.display()))?;
    Ok(format!("No printer reachable via lp; opened the PDF to print from your viewer: {}", path.display()))
}

/// Writes the PDF that [`print`] sends to the printer and returns its path (no printing).
pub fn print_pdf_path(a: &Article, style: CitationStyle) -> Result<PathBuf> {
    let path = temp_path(&a.title, "pdf")?;
    to_pdf(a, style, &path)?;
    Ok(path)
}

/// Open the user's mail client with the article as text (mailto: subject + body; long
/// articles are truncated with a note and the .txt saved to a temp file whose path is given).
pub fn email(a: &Article, style: CitationStyle) -> Result<()> {
    let draft = prepare_email(a, style)?;
    // TODO(windows): `open` handles mailto: there too, but very long URLs may be cut by the shell.
    open::that_detached(&draft.url).context("could not open the mail client")?;
    Ok(())
}

/// What [`email`] opens: the mailto: URL and, for long articles, the saved full .txt.
#[derive(Clone, Debug, PartialEq)]
pub struct EmailDraft {
    pub url: String,
    /// The full article as a text file (only when the body had to be truncated).
    pub full_text_file: Option<PathBuf>,
}

/// Maximum body length (in characters, before percent-encoding) put in a mailto: URL.
pub const EMAIL_BODY_LIMIT: usize = 1800;

/// Build the email without launching anything: saves the full .txt to a temp file when the
/// body is too long for a mailto: link.
pub fn prepare_email(a: &Article, style: CitationStyle) -> Result<EmailDraft> {
    let body = to_txt(a, style);
    if body.chars().count() <= EMAIL_BODY_LIMIT {
        return Ok(EmailDraft { url: mailto_url(&email_subject(a), &body, None), full_text_file: None });
    }
    let path = temp_path(&a.title, "txt")?;
    std::fs::write(&path, &body).with_context(|| format!("could not write {}", path.display()))?;
    Ok(EmailDraft { url: mailto_url(&email_subject(a), &body, Some(&path)), full_text_file: Some(path) })
}

/// Subject line: the label and title, so the AI status is visible in the inbox too.
pub fn email_subject(a: &Article) -> String {
    let short = match a.kind {
        ArticleKind::Interpretation => "AI interpretation",
        ArticleKind::FullText => "Open-access paper",
        ArticleKind::AiOnly => "AI article",
        ArticleKind::News => "AI news summary",
        ArticleKind::Learn => "Learn AI explanation",
    };
    format!("{short}: {} (Gateless Scholar)", a.title.trim())
}

/// Pure mailto: URL builder. `body` is truncated to [`EMAIL_BODY_LIMIT`] characters at a line
/// boundary when needed, followed by a note pointing at `full_file` (when given).
pub fn mailto_url(subject: &str, body: &str, full_file: Option<&Path>) -> String {
    let body = truncate_body(body, full_file);
    format!("mailto:?subject={}&body={}", percent_encode(subject), percent_encode(&body.replace('\n', "\r\n")))
}

fn truncate_body(body: &str, full_file: Option<&Path>) -> String {
    if body.chars().count() <= EMAIL_BODY_LIMIT {
        return body.to_string();
    }
    let note = match full_file {
        Some(p) => format!(
            "\n\n[…] The article is too long for an email link and was cut here.\nFull article attached as text file: {}\n(Please attach this file to the email before sending.)\n",
            p.display()
        ),
        None => "\n\n[…] The article is too long for an email link and was cut here.\n".to_string(),
    };
    let budget = EMAIL_BODY_LIMIT.saturating_sub(note.chars().count()).max(200);
    let cut: String = body.chars().take(budget).collect();
    // Cut at the last line break so no passage marker is left half-open mid-line.
    let cut = match cut.rfind('\n') {
        Some(i) if i > cut.len() / 2 => cut[..i].to_string(),
        _ => cut,
    };
    format!("{}{note}", cut.trim_end())
}

/// RFC 3986 percent-encoding of everything but unreserved characters (UTF-8).
pub fn percent_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len() * 3);
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => out.push(b as char),
            _ => out.push_str(&format!("%{b:02X}")),
        }
    }
    out
}

/// A file-name-safe slug of the title (for default export file names too).
pub fn file_stem(title: &str) -> String {
    let mut s = String::new();
    for c in title.chars() {
        if c.is_alphanumeric() {
            s.extend(c.to_lowercase());
        } else if !s.ends_with('-') && !s.is_empty() {
            s.push('-');
        }
        if s.chars().count() >= 60 {
            break;
        }
    }
    let s = s.trim_matches('-').to_string();
    if s.is_empty() { "article".into() } else { s }
}

fn temp_path(title: &str, ext: &str) -> Result<PathBuf> {
    let dir = std::env::temp_dir().join("gateless-scholar");
    std::fs::create_dir_all(&dir).with_context(|| format!("could not create {}", dir.display()))?;
    let id = uuid::Uuid::new_v4().simple().to_string();
    Ok(dir.join(format!("{}-{}.{ext}", file_stem(title), id.get(..8).unwrap_or("x"))))
}

fn find_in_path(cmd: &str) -> Option<PathBuf> {
    let path = std::env::var_os("PATH")?;
    std::env::split_paths(&path).map(|d| d.join(cmd)).find(|p| p.is_file())
}

