/// The legend shown at the top of every export.
pub const LEGEND: [(Origin, &str); 3] = [
    (Origin::Original, "Original text: verbatim from the source."),
    (Origin::Reworded, "AI-reworded original: the source's text lightly reworded by the AI for flow; the original wording is given."),
    (Origin::AiWritten, "AI-written: written by the AI from the numbered sources; every claim cites a source [n]."),
];

pub(crate) struct Front {
    pub label: String,
    pub title: String,
    pub standfirst: Option<String>,
    pub byline: String,
    pub generated: String,
    /// "Original paper: <title> — <authors>" and its link.
    pub original: Option<(String, Option<String>)>,
    pub hero: Option<ImageRef>,
}

pub(crate) fn front(a: &Article) -> Front {
    let byline = if a.byline.trim().is_empty() { "Gateless Scholar".to_string() } else { a.byline.trim().to_string() };
    let generated = if a.generated_by.trim().is_empty() {
        format!("Generated on {}", cite::long_date(a.created.date_naive()))
    } else {
        format!("Generated by {} on {}", a.generated_by.trim(), cite::long_date(a.created.date_naive()))
    };
    let original = if a.original_title.is_some() || a.original_url.is_some() {
        let mut t = format!("Original paper: {}", a.original_title.as_deref().unwrap_or("(untitled)").trim());
        if !a.original_authors.is_empty() {
            let p = Paper { authors: a.original_authors.clone(), ..Default::default() };
            t.push_str(&format!(" — {}", p.author_line(6)));
        }
        Some((t, a.original_url.clone().filter(|u| !u.trim().is_empty())))
    } else {
        None
    };
    Front {
        label: a.kind.label().to_string(),
        title: a.title.trim().to_string(),
        standfirst: a.standfirst.clone().filter(|s| !s.trim().is_empty()),
        byline: format!("By {byline}"),
        generated,
        original,
        hero: a.hero_image.clone(),
    }
}

pub(crate) struct RefEntry {
    pub n: u32,
    pub text: String,
    pub link: Option<String>,
}

/// The reference list, numbered by source id so it matches the "[n]" in the text.
pub(crate) fn reference_entries(a: &Article, style: CitationStyle) -> Vec<RefEntry> {
    let mut srcs: Vec<&Source> = a.sources.iter().collect();
    srcs.sort_by_key(|s| s.id);
    srcs.dedup_by_key(|s| s.id);
    srcs.into_iter().map(|s| RefEntry { n: s.id, text: cite::reference(s, style), link: s.link() }).collect()
}

pub(crate) fn references_heading(style: CitationStyle) -> String {
    format!("References ({})", style.label())
}

/// Human-readable validation notes.
pub(crate) fn validation_lines(a: &Article) -> Vec<String> {
    let v = &a.validation;
    let mut out = Vec::new();
    let plural = |n: u32, one: &str, many: &str| if n == 1 { one.to_string() } else { many.to_string() };
    if v.invalid_citations_removed > 0 {
        out.push(format!(
            "{} {} that did not match a real source {} removed.",
            v.invalid_citations_removed,
            plural(v.invalid_citations_removed, "citation", "citations"),
            plural(v.invalid_citations_removed, "was", "were")
        ));
    }
    if v.unverified_sentences > 0 {
        out.push(format!(
            "{} {} without a supporting source {} marked [unverified].",
            v.unverified_sentences,
            plural(v.unverified_sentences, "sentence", "sentences"),
            plural(v.unverified_sentences, "is", "are")
        ));
    }
    if v.charts_rejected > 0 {
        out.push(format!(
            "{} {} rejected because the numbers were not found in the sources.",
            v.charts_rejected,
            plural(v.charts_rejected, "chart was", "charts were")
        ));
    }
    if v.rewordings_reverted > 0 {
        out.push(format!(
            "{} {} reverted to the original wording.",
            v.rewordings_reverted,
            plural(v.rewordings_reverted, "rewording was", "rewordings were")
        ));
    }
    out.extend(v.notes.iter().filter(|n| !n.trim().is_empty()).cloned());
    out
}

/// "[1, 3]" for a passage's citations (empty string when none).
pub(crate) fn cite_marker(c: &[u32]) -> String {
    if c.is_empty() {
        return String::new();
    }
    let parts: Vec<String> = c.iter().map(u32::to_string).collect();
    format!("[{}]", parts.join(", "))
}

pub(crate) fn chart_kind_name(k: ChartKind) -> &'static str {
    match k {
        ChartKind::Bar => "Bar chart",
        ChartKind::Line => "Line chart",
        ChartKind::Venn => "Venn diagram",
        ChartKind::Stock => "Stock-style chart",
        ChartKind::Flow => "Flow diagram",
    }
}

/// Caption under every chart: what it is, that the AI specified it, and where the numbers are from.
pub(crate) fn chart_caption(c: &ChartSpec) -> String {
    let src = if c.citations.is_empty() {
        "no source given [unverified]".to_string()
    } else {
        format!("data from {}", cite_marker(&c.citations))
    };
    format!("{} specified by the AI and drawn by Gateless Scholar; {src}.", chart_kind_name(c.kind))
}

pub(crate) fn fmt_num(v: f64) -> String {
    if !v.is_finite() {
        return "–".into();
    }
    if v.fract().abs() < 1e-9 && v.abs() < 1e15 {
        format!("{}", v as i64)
    } else {
        let s = format!("{v:.3}");
        s.trim_end_matches('0').trim_end_matches('.').to_string()
    }
}

/// The chart's data as a table: header row and data rows.
pub(crate) fn chart_table(c: &ChartSpec) -> (Vec<String>, Vec<Vec<String>>) {
    match c.kind {
        ChartKind::Bar | ChartKind::Line | ChartKind::Stock => {
            let mut xs: Vec<String> = Vec::new();
            for s in &c.series {
                for (x, _) in &s.points {
                    if !xs.contains(x) {
                        xs.push(x.clone());
                    }
                }
            }
            let mut header = vec![c.x_label.clone().unwrap_or_else(|| "".into())];
            header.extend(c.series.iter().map(|s| {
                if s.name.trim().is_empty() { c.y_label.clone().unwrap_or_else(|| "Value".into()) } else { s.name.clone() }
            }));
            let rows = xs
                .iter()
                .map(|x| {
                    let mut row = vec![x.clone()];
                    for s in &c.series {
                        row.push(s.points.iter().find(|(px, _)| px == x).map(|(_, v)| fmt_num(*v)).unwrap_or_default());
                    }
                    row
                })
                .collect();
            (header, rows)
        }
        ChartKind::Venn => {
            let header = vec!["Set".to_string(), "Size".to_string()];
            let mut rows = Vec::new();
            for s in &c.sets {
                rows.push(vec![s.label.clone(), fmt_num(s.size)]);
            }
            for (i, s) in c.sets.iter().enumerate() {
                for (j, v) in &s.overlaps {
                    if *j > i
                        && let Some(o) = c.sets.get(*j)
                    {
                        rows.push(vec![format!("{} ∩ {}", s.label, o.label), fmt_num(*v)]);
                    }
                }
            }
            (header, rows)
        }
        ChartKind::Flow => {
            let header = vec!["From".to_string(), "To".to_string(), "Label".to_string()];
            let name = |i: usize| c.nodes.get(i).cloned().unwrap_or_else(|| format!("#{i}"));
            let mut rows: Vec<Vec<String>> = c.edges.iter().map(|(f, t, l)| vec![name(*f), name(*t), l.clone()]).collect();
            if rows.is_empty() {
                rows = c.nodes.iter().map(|n| vec![n.clone(), String::new(), String::new()]).collect();
            }
            (header, rows)
        }
    }
}

/// Caption for a real image: title, credit, licence, source, and the "may not be from the paper" note.
pub(crate) fn image_caption(img: &ImageRef) -> String {
    let mut parts = Vec::new();
    if !img.title.trim().is_empty() {
        parts.push(img.title.trim().to_string());
    }
    if !img.credit.trim().is_empty() {
        parts.push(format!("Credit: {}", img.credit.trim()));
    }
    if !img.licence.trim().is_empty() {
        parts.push(format!("Licence: {}", img.licence.trim()));
    }
    let mut s = parts.join(". ");
    if !s.is_empty() {
        s.push('.');
    }
    if !img.from_paper {
        s.push_str(" May not be from the paper.");
    }
    if !img.embeddable {
        s.push_str(" Copyrighted image: link only.");
    }
    s.trim().to_string()
}

/// The page to link for an image (its description page, else the file).
pub(crate) fn image_link(img: &ImageRef) -> Option<String> {
    [&img.page_url, &img.url].into_iter().find(|u| !u.trim().is_empty()).cloned()
}

/// Consecutive passages with the same origin merged into runs, so markers wrap whole runs.
pub(crate) fn passage_runs(ps: &[Passage]) -> Vec<Vec<&Passage>> {
    let mut out: Vec<Vec<&Passage>> = Vec::new();
    for p in ps {
        match out.last_mut() {
            // Reworded passages each keep their own original, so they are never merged.
            Some(run) if run[0].origin == p.origin && p.origin != Origin::Reworded => run.push(p),
            _ => out.push(vec![p]),
        }
    }
    out
}
